E.mount=function(){prev.mount();this.rbSelection=null;this.rbPoints=[];this.rbPanel=false;const group=V.$('.editor-tool-group');for(const [tool,label,key]of [['rooms','Rooms & Doors','Q'],['door','Adicionar porta','O'],['wall','Parede interna',''],['vertices','Editar vértices',''],['navpoint','Destino de atividade','']]){const b=document.createElement('button');b.dataset.editorTool=tool;b.innerHTML=label+(key?' <kbd>'+key+'</kbd>':'');b.onclick=()=>this.setTool(tool);group.appendChild(b);}const option=document.createElement('option');option.value=String(8/T);option.textContent='8 pixels';V.$('#editor-snap').appendChild(option);V.$('#editor-snap').value=String(this.snap);const panel=document.createElement('section');panel.id='rb-room-panel';panel.hidden=true;panel.innerHTML='<div class="rb-eyebrow">CONSTRUIR E CONECTAR</div><h3>Rooms & Doors</h3><p class="editor-muted">Crie cômodos e escolha para onde cada porta leva.</p><div class="rb-buttons">'+button('rb-create','＋ Novo cômodo','primary')+button('rb-building','＋ Novo edifício')+button('rb-add-door','＋ Porta')+button('rb-graph','Ver conexões')+button('rb-actor','＋ Pessoa / animal')+'</div><label class="rb-field" for="rb-room-search"><span>Buscar lugares</span><input id="rb-room-search" type="search" placeholder="Sala, edifício, piso…"></label><div id="rb-room-list"></div>';V.$('.editor-palette').appendChild(panel);V.$('#rb-create').onclick=()=>this.roomForm();V.$('#rb-building').onclick=()=>this.buildingForm();V.$('#rb-add-door').onclick=()=>this.setTool('door');V.$('#rb-graph').onclick=()=>this.graphForm();V.$('#rb-actor').onclick=()=>this.actorForm();V.$('#rb-room-search').oninput=()=>this.roomList();this.updateMapList();V.$('#editor-map').onchange=e=>this.visitMap(e.target.value);V.$('#editor-export').onclick=()=>{V.Save.download('voices-cenarios-v2.3-salas-portas.json',D.document(this.drafts));this.message('Cenários exportados com salas, portas, pessoas e navegação.');};};
