E.createRoom=function(opts,sourceDoor=null){if(opts.location==='here'&&!opts.polygon){const room=R.makeRoom(opts);this.pendingPlacement={room,sourceDoor,before:this.fullSnapshot()};if(this.design().builderMap){this.design().width=Math.min(96,this.design().width+Math.ceil(R.box(room.polygon).w/T)+2);this.design().height=Math.min(96,Math.max(this.design().height,Math.ceil((R.box(room.polygon).h+240)/T)));}this.setTool('rooms');this.refresh(true);this.message('Clique no mapa para posicionar '+room.name+'.');return true;}return this.transaction('Criar '+opts.name+(sourceDoor?' e conectar a porta':''),()=>{const room=R.makeRoom(opts);let id=this.mapId;if(opts.location==='new'){id=R.id('interior');this.drafts[id]=R.makeDesign(room);}else{const d=this.design();if(opts.polygon)room.polygon=opts.polygon;else{this.pendingPlacement={room,sourceDoor};this.setTool('rooms');this.message('Clique no mapa para posicionar '+room.name+'.');return;}this.construction().rooms.push(room);}R.sync(this.drafts);if(sourceDoor)R.connect(this.drafts,sourceDoor.map,sourceDoor.id,id,room.id,{side:opts.side});this.mapId=id;this.rbSelection={kind:'room',id:room.id};this.rbPanel=true;this.setTool('rooms');this.selection=null;this.showRoomPanel();this.updateMapList();});};
