E.transformRoom=function(room,opts={}){return this.transaction('Editar geometria de '+room.name,()=>{const old=copy(room),b=R.box(old.polygon),sx=(opts.width||b.w)/b.w,sy=(opts.height||b.h)/b.h,dx=opts.dx||0,dy=opts.dy||0,angle=(opts.rotate||0)*Math.PI/180,cx=b.x+b.w/2,cy=b.y+b.h/2;const transform=p=>{let x=b.x+(p[0]-b.x)*sx+dx,y=b.y+(p[1]-b.y)*sy+dy;if(angle){const xx=x-cx-dx,yy=y-cy-dy;x=cx+dx+xx*Math.cos(angle)-yy*Math.sin(angle);y=cy+dy+xx*Math.sin(angle)+yy*Math.cos(angle);}return[x,y];};room.polygon=opts.polygon||opts.shape&&opts.shape!==old.shape?opts.polygon||R.polygon(opts.shape,opts.width||b.w,opts.height||b.h,b.x+dx,b.y+dy):old.polygon.map(transform);if(!R.validPolygon(room.polygon))throw Error('O contorno cruza a si mesmo ou possui segmentos muito curtos.');for(const key of ['name','building','floor','floorStyle','wallStyle','category','shape'])if(opts[key]!==undefined)room[key]=opts[key];room.walls=old.walls.map(w=>({...w,a:transform(w.a),b:transform(w.b)}));for(const door of this.construction().doors.filter(d=>d.room===room.id)){const s=R.segments(room).find(s=>s.key===door.wall);if(!s)throw Error('O novo formato remove uma parede com porta. Remova ou reconecte a porta antes.');door.x=s.a[0]+(s.b[0]-s.a[0])*door.u;door.y=s.a[1]+(s.b[1]-s.a[1])*door.u;door.normal=R.normal(s,this.design());}
 if(!opts.polygon)for(const row of this.design().decor)if(R.pointIn(row[2]*T+24,row[3]*T+24,old.polygon)){const p=transform([row[2]*T,row[3]*T]);row[2]=p[0]/T;row[3]=p[1]/T;}if(!opts.polygon)for(const scene of this.design().scenes)if(R.pointIn(scene.x*T+24,scene.y*T+24,old.polygon)){const p=transform([scene.x*T+24,scene.y*T+24]);scene.x=p[0]/T-.5;scene.y=p[1]/T-.5;}
 if(this.design().builderMap){const bb=R.box(room.polygon);this.design().width=Math.max(this.design().width,Math.ceil((bb.x+bb.w+96)/T));this.design().height=Math.max(this.design().height,Math.ceil((bb.y+bb.h+96)/T));if(this.design().width>96||this.design().height>96)throw Error('O interior pode ter até 96 × 96 blocos.');if(this.construction().rooms.length===1){this.design().name=room.name;this.design().outline=room.polygon.map(p=>p.map(n=>n/T));}}const m=D.preview(this.mapId,this.design()),issues=R.validation(m).filter(i=>i.id===room.id||this.construction().doors.some(d=>d.id===i.id&&d.room===room.id)&&!i.message.startsWith('Porta sem destino'));if(issues.length)throw Error(issues[0].message);this.refreshArrivals();});};
E.refreshArrivals=function(){for(const [map,d]of Object.entries(this.drafts))for(const door of R.structure(d).doors){if(!door.to?.door)continue;const dest=this.drafts[door.to.map],back=R.structure(dest).doors.find(p=>p.id===door.to.door);if(back){const p=R.approach(D.preview(door.to.map,dest),back);if(!p)throw Error('Uma chegada ficou bloqueada.');door.to.arrival={x:p.x,y:p.y,dir:R.inwardDirection(back)};}}};
E.placeDoor=function(p){const before=this.fullSnapshot();try{const door=R.doorAt(this.design(),p);const m=D.preview(this.mapId,this.design());if(!door.wall&&V.Living.blocked(m,door.x,door.y,12))throw Error('Selecione uma parede construída ou uma entrada livre.');const s=this.construction();if(s.doors.some(o=>Math.hypot(o.x-door.x,o.y-door.y)<(o.width+door.width)/2+8))throw Error('Abra espaço entre as portas.');s.doors.push(door);this.rbSelection={kind:'door',id:door.id};this.commitWorld(before,'Adicionar porta');this.doorDestination(door);}catch(err){this.drafts=before.maps;this.formError(err.message);this.message(err.message);}};
E.doorDestination=function(door=this.door()){if(!door)return;const src={map:this.mapId,id:door.id};this.sheet('Para onde esta porta leva?',`<div class="rb-destination-options"><button id="rb-existing" class="rb-destination"><b>Conectar a um lugar existente</b><span>Escolha um cômodo ou mapa e defina a chegada.</span></button><button id="rb-new" class="rb-destination"><b>Criar novo cômodo</b><span>Desenhe a sala, gere a entrada e crie o retorno automaticamente.</span></button></div><p class="editor-muted">O destino pode ser um interior, outro andar ou um cenário exterior.</p>`);V.$('#rb-existing').onclick=()=>this.destinationForm(src);V.$('#rb-new').onclick=()=>this.roomForm(src);};
E.destinationOptions=function(q=''){const list=[];for(const [id,d]of Object.entries(this.drafts)){const rooms=R.structure(d).rooms;if(rooms.length)for(const r of rooms)list.push([id+'|'+r.id,r.name+' · '+r.building+' · piso '+r.floor]);else list.push([id+'|',d.name||id]);}return list.filter(([id,name])=>name.toLowerCase().includes(q.toLowerCase()));};
E.destinationForm=function(src){this.sheet('Conectar porta existente',`<label class="rb-field" for="rb-destination-search"><span>Buscar salas e mapas</span><input id="rb-destination-search" type="search" placeholder="Biblioteca, cozinha, praça…"></label>${select('rb-destination','Destino',this.destinationOptions(),'library|')}${select('rb-destination-door','Entrada no destino',[['','Criar porta de retorno automaticamente']],'')}${select('rb-dest-side','Parede da nova entrada',[['south','Embaixo'],['north','Em cima'],['west','Esquerda'],['east','Direita']],'south')}${check('rb-one-way','Somente ida (sem porta de retorno)',false)}<div id="rb-link-preview" class="rb-link-preview"></div><details><summary>Chegada personalizada</summary><p class="editor-muted">Deixe vazio para encontrar uma chegada livre automaticamente. Ou escolha o local visualmente.</p><div class="rb-form-grid">${input('rb-arrival-x','X (pixels)','','number')}${input('rb-arrival-y','Y (pixels)','','number')}</div>${button('rb-pick-destination','Escolher porta e chegada no mapa')}</details>`,button('rb-connect-confirm','Conectar e criar retorno','primary'));const update=()=>{const [id,room]=val('rb-destination').split('|'),doors=R.structure(this.drafts[id]).doors.filter(d=>(!room||d.room===room)&&!d.to&&d.id!==src.id);V.$('#rb-destination-door').innerHTML='<option value="">Criar porta de retorno automaticamente</option>'+doors.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('');V.$('#rb-link-preview').innerHTML=`<strong>${esc(this.drafts[src.map].name||src.map)}</strong><span>↔</span><strong>${esc(this.drafts[id].name||id)}</strong>`;};V.$('#rb-destination').onchange=update;V.$('#rb-destination-search').oninput=()=>{const opts=this.destinationOptions(val('rb-destination-search'));V.$('#rb-destination').innerHTML=opts.map(([v,n])=>`<option value="${v}">${esc(n)}</option>`).join('');if(opts.length)update();};update();V.$('#rb-pick-destination').onclick=()=>{const [map,room]=val('rb-destination').split('|');this.pendingDestination={src,map,room,oneWay:checked('rb-one-way'),phase:'door'};this.closeSheet();this.visitMap(map);this.setTool('door');this.message('Destino: clique na parede para colocar a porta; depois escolha a chegada livre.');};V.$('#rb-connect-confirm').onclick=()=>{const [map,room]=val('rb-destination').split('|'),opts={oneWay:checked('rb-one-way'),side:val('rb-dest-side'),targetDoor:val('rb-destination-door')};if(val('rb-arrival-x')!==''&&val('rb-arrival-y')!=='')opts.arrival={x:Number(val('rb-arrival-x')),y:Number(val('rb-arrival-y'))};if(this.transaction('Conectar porta e retorno',()=>{R.connect(this.drafts,src.map,src.id,map,room||null,opts);this.mapId=src.map;this.rbSelection={kind:'door',id:src.id};}))this.closeSheet();else this.formError(V.$('#editor-status-text').textContent);};};
E.inspector=function(){if(!this.rbPanel&&!this.rbSelection)return prev.inspector();const root=V.$('#editor-inspector-content');if(!root)return;const room=this.room(),door=this.door();if(door){root.innerHTML=`<div class="rb-eyebrow">PORTA FUNCIONAL</div><h3>${esc(door.name)}</h3>${input('rb-door-name','Nome',door.name)}${select('rb-door-type','Tipo',types,door.type)}<div class="rb-form-grid">${input('rb-door-width','Largura (px)',door.width,'number','min="32" max="192" step="8"')}${input('rb-door-height','Altura (px)',door.height,'number','min="32" max="160" step="8"')}</div>${select('rb-door-appearance','Textura original',walls,door.appearance)}${select('rb-door-facing','Direção de entrada',[[0,'Sul'],[1,'Oeste'],[2,'Leste'],[3,'Norte']],door.facing)}${select('rb-door-mode','Abrir ao…',[['interact','Interagir (E)'],['auto','Cruzar a abertura']],door.mode)}${select('rb-door-transition','Transição',[['fade','Fade'],['slide','Deslocamento'],['none','Imediata']],door.transition)}${select('rb-door-sound','Som opcional',[['','Sem som'],['portal','Passagem'],['menu','Clique'],['collect','Sinal']],door.sound)}${check('rb-door-locked','Trancada',door.locked)}${check('rb-door-npc','Permitir NPCs',door.npcAccess)}${input('rb-door-permissions','NPCs permitidos (IDs separados por vírgula)',door.npcAllow.join(', '))}<details><summary>Condições narrativas</summary>${input('rb-door-flag','Flag da história',door.conditions.flag||'')}${select('rb-door-quest','Missão concluída',[['','Nenhuma'],...(V.Living.missions||[]).map(q=>[q.id,q.title||q.id])],door.conditions.quest||'')}${select('rb-door-chapter','Capítulo concluído',[['','Nenhum'],...[1,2,3,4,5,6].map(n=>[n,'Capítulo '+n])],door.conditions.chapter||'')}</details><p class="rb-destination-summary">${door.entranceOnly?'Entrada de mão única · sem saída de retorno.':door.to?'→ '+esc(this.drafts[door.to.map]?.name||door.to.map)+'<br>'+Math.round(door.to.arrival.x)+', '+Math.round(door.to.arrival.y)+' px · '+(door.pair?'ida e volta':'somente ida'):'Escolha um destino para ativar a porta.'}</p><div class="rb-buttons">${button('rb-door-save','Salvar propriedades','primary')}${button('rb-door-link','Escolher / reconectar destino')}${button('rb-door-test','Testar transição')}${button('rb-door-enter','Editar destino')}${button('rb-door-unlink','Remover conexão')}${button('rb-door-delete','Excluir porta')}</div>`;V.$('#rb-door-save').onclick=()=>this.transaction('Editar porta',()=>{door.name=val('rb-door-name').slice(0,90);door.type=val('rb-door-type');door.width=Number(val('rb-door-width'));door.height=Number(val('rb-door-height'));if(door.width<32||door.width>192||door.height<32||door.height>160)throw Error('Tamanho de porta inválido.');door.appearance=Number(val('rb-door-appearance'));door.facing=Number(val('rb-door-facing'));door.mode=val('rb-door-mode');door.transition=val('rb-door-transition');door.sound=val('rb-door-sound');door.locked=checked('rb-door-locked');door.npcAccess=checked('rb-door-npc');door.npcAllow=val('rb-door-permissions').split(',').map(s=>s.trim()).filter(Boolean);door.conditions={flag:val('rb-door-flag').trim(),quest:val('rb-door-quest'),chapter:Number(val('rb-door-chapter'))||null};if(!door.wall)door.normal=({0:{x:0,y:-1},1:{x:1,y:0},2:{x:-1,y:0},3:{x:0,y:1}})[door.facing];});V.$('#rb-door-link').onclick=()=>this.doorDestination();V.$('#rb-door-test').onclick=()=>{this.toggleWalk(true);R.transition(door,true);};V.$('#rb-door-enter').onclick=()=>{if(door.to)this.visitMap(door.to.map);else this.message('Primeiro escolha um destino.');};V.$('#rb-door-unlink').onclick=()=>this.transaction('Desconectar porta',()=>R.disconnect(this.drafts,this.mapId,door.id));V.$('#rb-door-delete').onclick=()=>this.deleteDoor(door);return;}
 if(room){const b=R.box(room.polygon);root.innerHTML=`<div class="rb-eyebrow">GEOMETRIA JOGÁVEL</div><h3>${esc(room.name)}</h3><p class="editor-muted">${esc(R.shapes[room.shape])} · ${Math.round(b.w)} × ${Math.round(b.h)} px<br>${esc(room.building)} · piso ${room.floor}</p><div class="rb-form-grid">${input('rb-room-x','X (px)',b.x,'number','step="8"')}${input('rb-room-y','Y (px)',b.y,'number','step="8"')}</div><div class="rb-buttons">${button('rb-room-move','Mover sala')}${button('rb-room-edit','Nome, tamanho e materiais','primary')}${button('rb-room-vertices','Arrastar vértices')}${button('rb-room-rotate','Girar 90°')}${button('rb-room-door','Adicionar porta')}${button('rb-room-wall','Adicionar parede interna')}${button('rb-room-duplicate','Duplicar layout')}${button('rb-room-delete','Excluir sala')}</div><h4>Entradas e saídas</h4><div class="rb-door-list">${this.construction().doors.filter(d=>d.room===room.id).map(d=>`<button data-rb-door="${d.id}">${esc(d.name)}<small>${d.to?'→ '+esc(this.drafts[d.to.map]?.name||d.to.map):'⚠ Sem destino'}</small></button>`).join('')||'<p class="editor-muted">Adicione uma porta à parede desta sala.</p>'}</div><h4>Paredes internas</h4>${room.walls.map(w=>`<button data-rb-wall="${w.id}" class="quiet">Excluir parede ${esc(w.id.slice(-6))}</button>`).join('')}`;V.$('#rb-room-move').onclick=()=>this.transformRoom(room,{dx:Number(val('rb-room-x'))-b.x,dy:Number(val('rb-room-y'))-b.y});V.$('#rb-room-edit').onclick=()=>this.roomForm(null,room);V.$('#rb-room-vertices').onclick=()=>this.setTool('vertices');V.$('#rb-room-rotate').onclick=()=>this.transformRoom(room,{rotate:90});V.$('#rb-room-door').onclick=()=>this.setTool('door');V.$('#rb-room-wall').onclick=()=>this.setTool('wall');V.$('#rb-room-duplicate').onclick=()=>this.duplicateRoom(room);V.$('#rb-room-delete').onclick=()=>this.deleteRoom(room);V.$$('[data-rb-door]').forEach(b=>b.onclick=()=>{this.rbSelection={kind:'door',id:b.dataset.rbDoor};this.inspector();this.paint();});V.$$('[data-rb-wall]').forEach(b=>b.onclick=()=>this.transaction('Excluir parede e suas portas',()=>{const ids=this.construction().doors.filter(d=>d.wall===b.dataset.rbWall).map(d=>d.id);for(const id of ids){R.disconnect(this.drafts,this.mapId,id);this.construction().doors=this.construction().doors.filter(d=>d.id!==id);}room.walls=room.walls.filter(w=>w.id!==b.dataset.rbWall);}));return;}
 root.innerHTML=`<div class="rb-eyebrow">CONSTRUÇÃO VISUAL</div><h3>Salas e portas</h3><p>Crie um espaço, escolha seu formato e conecte-o ao bairro.</p><div class="rb-buttons">${button('rb-ins-new','＋ Novo cômodo','primary')}${button('rb-ins-door','＋ Adicionar porta')}${button('rb-ins-graph','Mapa de conexões')}</div><p class="editor-muted">${this.pendingPlacement?'Clique no mapa para posicionar a sala.':this.tool==='polygon'?'Clique para adicionar pontos. Enter fecha; Backspace remove; Esc cancela.':this.tool==='wall'?'Clique em dois pontos para formar a parede.':this.tool==='door'?'Clique em uma parede ou entrada livre.':'Clique em uma sala para editar. Arraste para mover o contorno.'}</p>${this.tool==='polygon'?button('rb-polygon-done','Fechar contorno','primary'):''}`;V.$('#rb-ins-new').onclick=()=>this.roomForm();V.$('#rb-ins-door').onclick=()=>this.setTool('door');V.$('#rb-ins-graph').onclick=()=>this.graphForm();if(V.$('#rb-polygon-done'))V.$('#rb-polygon-done').onclick=()=>this.finishPolygon();};
E.deleteDoor=function(door){this.transaction('Excluir porta e limpar retorno',()=>{R.disconnect(this.drafts,this.mapId,door.id);this.construction().doors=this.construction().doors.filter(d=>d.id!==door.id);this.rbSelection=null;});};
E.deleteRoom=function(room){const source=this.mapId,links=[];for(const [id,d]of Object.entries(this.drafts))for(const door of R.structure(d).doors)if(id===source&&door.room===room.id||door.to?.map===source&&door.to?.room===room.id)links.push({map:id,door});this.sheet('Excluir '+room.name,`<p>Esta sala possui ${links.length} portas ou referências. As portas que levam a ela e seus retornos serão removidos juntos.</p><p>${this.design().builderMap&&this.construction().rooms.length===1?'O interior e seus objetos serão removidos.':'Os móveis e objetos do cenário serão preservados.'} Desfazer recupera a sala e todas as conexões.</p>`,button('rb-delete-confirm','Excluir sala e conexões','primary'));V.$('#rb-delete-confirm').onclick=()=>{this.closeSheet();this.transaction('Excluir sala e limpar dependências',()=>{for(const {map,door}of links){R.disconnect(this.drafts,map,door.id);this.drafts[map].construction.doors=this.drafts[map].construction.doors.filter(d=>d.id!==door.id);}const d=this.drafts[source];d.construction.rooms=d.construction.rooms.filter(r=>r.id!==room.id);this.rbSelection=null;if(d.builderMap&&!d.construction.rooms.length){delete this.drafts[source];for(const cfg of Object.values(this.drafts))for(const a of R.structure(cfg).actors)a.itinerary=a.itinerary.filter(p=>(typeof p==='string'?p:p.map)!==source);this.mapId='hub';}});};};
E.duplicateRoom=function(room){this.transaction('Duplicar layout de '+room.name,()=>{const source=this.design(),b=R.box(room.polygon),r=copy(room),dx=96-b.x,dy=144-b.y;r.id=R.id('room');r.name+=' · cópia';r.polygon=r.polygon.map(p=>[p[0]+dx,p[1]+dy]);r.walls=r.walls.map(w=>({...w,id:R.id('wall'),a:[w.a[0]+dx,w.a[1]+dy],b:[w.b[0]+dx,w.b[1]+dy]}));const d=R.makeDesign(r);d.decor=copy(source.decor.filter(row=>R.pointIn(row[2]*T+24,row[3]*T+24,room.polygon))).map(row=>{row[2]+=dx/T;row[3]+=dy/T;row[6]={...row[6],id:R.id('custom-prop'),sceneIds:[],anchorIds:[],objectIds:[]};return row;});d.scenes=copy(source.scenes.filter(s=>R.pointIn(s.x*T+24,s.y*T+24,room.polygon))).map(s=>({...s,id:R.id('custom-scene'),x:s.x+dx/T,y:s.y+dy/T,hostDecor:null}));d.construction.actors=copy(R.structure(source).actors.filter(a=>R.pointIn(a.x,a.y,room.polygon))).map(a=>({...a,id:R.id('actor'),x:a.x+dx,y:a.y+dy,itinerary:[]}));const id=R.id('interior');this.drafts[id]=d;this.mapId=id;this.rbSelection={kind:'room',id:r.id};R.sync(this.drafts);});this.refresh(true);};
E.buildingForm=function(){this.sheet('Criar edifício com vários cômodos',input('rb-new-building','Nome do edifício','Casa das histórias')+input('rb-building-rooms','Cômodos (separe por vírgulas)','Hall, Sala, Cozinha, Quarto, Biblioteca')+select('rb-building-floor','Piso existente',floors(),3)+input('rb-building-level','Andar',0,'number','min="-20" max="100"')+check('rb-building-exterior','Conectar o hall a este cenário exterior',true)+'<p class="editor-muted">Cada cômodo usa o mesmo editor. As portas de ida e volta conectam a sequência, e você pode mudar formas, tamanhos e ligações depois.</p>',button('rb-build-confirm','Criar edifício conectado','primary'));V.$('#rb-build-confirm').onclick=()=>{const name=val('rb-new-building').trim(),names=val('rb-building-rooms').split(',').map(n=>n.trim()).filter(Boolean).slice(0,16),floorStyle=Number(val('rb-building-floor')),level=Number(val('rb-building-level')),exterior=checked('rb-building-exterior');if(!name||!names.length)return this.formError('Nomeie o edifício e pelo menos um cômodo.');this.closeSheet();this.transaction('Criar edifício '+name,()=>{const origin=this.mapId,made=names.map((n,i)=>{const room=R.makeRoom({name:n,building:name,floor:level,floorStyle,shape:i===0?'rectangle':i===names.length-1?'l':'rectangle',width:576,height:432}),id=R.id('interior');this.drafts[id]=R.makeDesign(room);return{id,room};});R.sync(this.drafts);for(let i=0;i<made.length-1;i++){const from=made[i],to=made[i+1],d=this.drafts[from.id],door=R.entrance(d,from.room,'east');door.name=to.room.name;d.construction.doors.push(door);R.connect(this.drafts,from.id,door.id,to.id,to.room.id,{side:'west'});}if(exterior){const d=this.drafts[origin],m=D.preview(origin,d),p=R.safe(m,{x:d.spawn[0]*T+24,y:d.spawn[1]*T+24});if(!p)throw Error('Não há espaço na entrada do exterior.');d.construction||={version:1,rooms:[],doors:[],actors:[],navigation:[]};const door=R.doorAt(d,p);door.name=name;d.construction.doors.push(door);R.connect(this.drafts,origin,door.id,made[0].id,made[0].room.id);}this.mapId=made[0].id;this.rbSelection={kind:'room',id:made[0].room.id};});this.refresh(true);};};
